using UnityEngine;using System.Collections;using System.Collections.Generic;
public class ParticlePoolManager:MonoBehaviour{public static ParticlePoolManager Instance{get;private set;}Queue<ParticleSystem>pool=new Queue<ParticleSystem>();
void Awake(){if(Instance!=null){Destroy(gameObject);return;}Instance=this;for(int i=0;i<16;i++)pool.Enqueue(MakePS());}
ParticleSystem MakePS(){var go=new GameObject("P");go.transform.SetParent(transform);go.SetActive(false);var ps=go.AddComponent<ParticleSystem>();var m=ps.main;m.duration=0.35f;m.loop=false;m.startLifetime=new ParticleSystem.MinMaxCurve(0.25f,0.55f);m.startSpeed=new ParticleSystem.MinMaxCurve(2f,8f);m.startSize=new ParticleSystem.MinMaxCurve(0.05f,0.18f);m.gravityModifier=0.18f;m.simulationSpace=ParticleSystemSimulationSpace.World;var e=ps.emission;e.rateOverTime=0;e.SetBursts(new[]{new ParticleSystem.Burst(0f,22)});var sh=ps.shape;sh.shapeType=ParticleSystemShapeType.Circle;sh.radius=0.1f;var cl=ps.colorOverLifetime;cl.enabled=true;var g=new Gradient();g.SetKeys(new[]{new GradientColorKey(Color.white,0f),new GradientColorKey(Color.white,1f)},new[]{new GradientAlphaKey(1f,0f),new GradientAlphaKey(0f,1f)});cl.color=g;go.GetComponent<ParticleSystemRenderer>().material=new Material(Shader.Find("Sprites/Default"));go.GetComponent<ParticleSystemRenderer>().sortingOrder=8;return ps;}
public void SpawnAt(Vector3 pos,Color col){var ps=pool.Count>0?pool.Dequeue():MakePS();ps.gameObject.SetActive(true);ps.transform.position=pos;var m=ps.main;m.startColor=new ParticleSystem.MinMaxGradient(new Color(col.r,col.g,col.b,1),Color.white);ps.Play();StartCoroutine(Ret(ps,0.7f));}
IEnumerator Ret(ParticleSystem ps,float d){yield return new WaitForSeconds(d);ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);ps.gameObject.SetActive(false);pool.Enqueue(ps);}}
